def choose_move(observation):
    # Minimal deterministic move based on common keys
    grid_w = observation.get("grid_width", observation.get("gridW", 0))
    grid_h = observation.get("grid_height", observation.get("gridH", 0))

    self_pos = observation.get("self_position", observation.get("self_pos", None))
    opp_pos = observation.get("opponent_position", observation.get("opp_pos", None))

    res = observation.get("resources", None)
    obstacles = observation.get("obstacles", None)
    rem = observation.get("remaining_resource_count", observation.get("remaining_resources", None))

    # Normalize position
    if self_pos is None:
        if isinstance(observation.get("self"), dict):
            self_pos = observation["self"].get("pos", None)
        elif isinstance(observation.get("player"), dict):
            self_pos = observation["player"].get("pos", None)
    if opp_pos is None and isinstance(observation.get("opponent"), dict):
        opp_pos = observation["opponent"].get("pos", None)

    if self_pos is None:
        return [0, 0]
    cx, cy = self_pos

    # Helper: in-bounds move
    def valid(dx, dy):
        nx, ny = cx + dx, cy + dy
        if grid_w and (nx < 0 or ny < 0 or nx >= grid_w or ny >= grid_h):
            return False
        if obstacles:
            for ob in obstacles:
                if isinstance(ob, (list, tuple)) and len(ob) >= 2:
                    ox, oy = ob[0], ob[1]
                    if ox == nx and oy == ny:
                        return False
        return True

    # 1) Seek nearby resource if available
    if isinstance(res, (list, tuple)):
        best = None
        bestd = 2
        for r in res:
            if not isinstance(r, (list, tuple)) or len(r) < 2:
                continue
            rx, ry = r[0], r[1]
            dx, dy = rx - cx, ry - cy
            d = abs(dx) + abs(dy)
            if d <= 1 and valid(dx, dy):
                return [dx, dy]
            if d < bestd and valid(dx, dy):
                bestd = d
                best = (dx, dy)
        if best is not None:
            return [best[0], best[1]]

    # 2) If opponent nearby, move toward them
    if opp_pos is not None:
        ox, oy = opp_pos
        dx, dy = ox - cx, oy - cy
        if abs(dx) + abs(dy) == 1 and valid(dx, dy):
            return [dx, dy]
        # chase in best axis
        cand = []
        if dx != 0:
            cand.append((dx // abs(dx), 0))
        if dy != 0:
            cand.append((0, dy // abs(dy)))
        for mx, my in cand:
            if valid(mx, my):
                return [mx, my]

    # 3) Default deterministic sweep: right, down, left, up
    moves = [(1,0),(0,1),(-1,0),(0,-1)]
    for dx, dy in moves:
        if valid(dx, dy):
            return [dx, dy]

    return [0, 0]

